  @override
  String get cycleInsightLate =>
      'دورتك متأخرة. هذا أكثر شيوعاً مما تظنين ولا يعني دائماً وجود مشكلة. الإجهاد، تغيرات النوم، المرض، التغير المفاجئ في الوزن، والتمارين المكثفة كلها يمكن أن تؤخر دورتك أياماً أو حتى أسابيع. إذا تجاوز التأخير أسبوعين، فمن المفيد التحدث مع شخص بالغ موثوق أو طبيب.';

  @override
  String get cycleInsightPeriodSoon =>
      'قد تصل دورتك في أي يوم الآن. مستويات البروجسترون تنخفض، وهذا ما يحفّز بدء الحيض. قد تشعرين بمزيد من العواطف أو التعب أو ألم أسفل الظهر — كلها علامات على أن جسمك يستعد. احرصي على حمل فوطة أو منتج للدورة معك تحسباً.';

  @override
  String get cycleInsightPeriod =>
      'دورتك هنا لأن جسمك لم يكن بحاجة لبطانة الرحم التي بناها هذا الشهر، فيقوم بإفرازها. يحدث هذا بسبب انخفاض الإستروجين والبروجسترون — هرمونيكي الأساسيين. تحدث التشنجات لأن الرحم ينقبض لإخراج البطانة. الراحة، الكمادات الحارة، والترطيب الجيد قد تساعدك حقاً الآن.';

  @override
  String get cycleInsightFollicular =>
      'ينمي جسمك الآن بويضة وينضجها داخل المبيضين. ارتفاع الإستروجين يقوم بعمل جيد — يعيد بناء بطانة الرحم ويعزز مزاجك وطاقتك. يشعر معظم الناس بأفضل حالاتهم في هذه المرحلة. إنه وقت رائع للنشاط والاجتماع والمهام التي تحتاج تركيزاً.';

  @override
  String get cycleInsightOvulation =>
      'يفرز جسمك بويضة اليوم. ارتفاع هرمون LH هو ما أطلق هذه العملية، والإستروجين في ذروته. قد تلاحظين إفرازات أصفى ومطاطية — هذا طبيعي تماماً ويساعد الجهاز التناسلي على أداء وظيفته. يشعر بعض الأشخاص بألم خفيف في أحد جانبي أسفل البطن خلال الإباضة، وهذا أيضاً طبيعي.';

  @override
  String get cycleInsightLuteal =>
      'بعد الإباضة، ينتج جسمك المزيد من البروجسترون للاستعداد لحمل محتمل. هذا الهرمون مسؤول عن معظم أعراض ما قبل الدورة — الانتفاخ، حساسية الثدي، تقلبات المزاج، والتعب كلها شائعة جداً في هذه المرحلة. إذا لم تأتِ الدورة، تصل هذه الأعراض إلى ذروتها قبل 5 إلى 7 أيام من قدومها. أنت لا تتخيلين الأمر، إنه هرموني.';

  @override
