  @override
  String get cyA1S1P1 =>
      'كل شهر، يمر جسمك بسلسلة من التغيرات المصممة للاستعداد لحمل محتمل. تُسمى هذه السلسلة من الأحداث بالدورة الشهرية. وهي تشمل دماغك ومبيضيكِ ورحمك وسلسلة من الإشارات الهرمونية المنظَّمة بدقة التي تعمل جميعها معاً في إيقاع متناسق.';

  @override
  String get cyA1S1P2 =>
      'الدورة الشهرية هي سلسلة من التغيرات الطبيعية في إنتاج الهرمونات وفي بنية الرحم والمبيضين ضمن الجهاز التناسلي الأنثوي. تتحكم الدورة المبيضية في إنتاج البويضات وإطلاقها، بينما تنظّم الدورة الرحمية تهيئة بطانة الرحم والحفاظ عليها لاستقبال الجنين. وتسير هاتان الدورتان معاً في الوقت نفسه وتكونان منسّقتين فيما بينهما.';

  @override
  String get cyA1S1P3 =>
      'بعبارة بسيطة: ينمو مبيضاكِ ويطلقان بويضة. ويبني رحمك بطانة سميكة وطرية تحسباً لتخصيب تلك البويضة. وإذا لم يحدث التخصيب، تتساقط البطانة. هذا التساقط هو الدورة الشهرية. ثم تبدأ العملية كلها من جديد.';

  @override
