      'خلال السنة الأولى أو السنتين بعد أول دورة، من الشائع والطبيعي جداً أن تكون الدورات غير منتظمة. بل في السنة الأولى بعد أول دورة، قد تصل نسبة دوراتك غير الإباضية إلى 80% — أي أنه لا يتم إطلاق أي بويضة.';

  @override
  String get cyA1S6P2 =>
      'يحدث ذلك لأن نظام التواصل الهرموني بين دماغك ومبيضيكِ — المسمى بمحور الوطاء-النخامية-المبيض — لا يزال في طور النضج. ويستغرق هذا النظام وقتاً ليجد إيقاعه. وخلال السنتين الأوليين بعد البلوغ الطمثي، تغيب الإباضة في نحو نصف الدورات. وبعد خمس سنوات من البلوغ الطمثي، تحدث الإباضة في نحو 75% من الدورات.';

  @override
