  @override
  String get cyA3S1P1 =>
      'يظن معظم الناس أن الهرمونات التناسلية جسدية بحتة — فهي تتحكم في دورتك، وانتهى الأمر. لكن الواقع أكثر إثارة بكثير. فالهرمونات التي تقود دورتك الشهرية هي ستيرويدات عصبية النشاط: تعبر الحاجز الدموي الدماغي، وتؤثر مباشرةً في الدماغ، وتشكّل مزاجك وذاكرتك ودافعيتك ونومك وشهيتك وحساسيتك للألم طوال الشهر.';

