  @override
  String get cyA3S2P2 =>
      'يبدأ التنظيم الهرموني في الوطاء، حيث يُفرز الهرمون المطلِق لموجهة الغدد التناسلية (GnRH) بشكل نبضي بدءاً من البلوغ. ويُنقل GnRH إلى الفص الأمامي من الغدة النخامية، حيث يشير إليها بإطلاق الهرمون المنبّه للجُريب (FSH) والهرمون المُلوتِن (LH). ثم ينتقل FSH وLH عبر مجرى الدم إلى المبيضين، محفّزين إنتاج الهرمونات الستيرويدية الجنسية من الخلايا الجريبية.';

  @override
