  @override
  String get cyA3FshP1 =>
      'وظيفة FSH الرئيسية هي المساعدة في تنظيم الدورة الشهرية. وعلى وجه التحديد، يحفّز FSH جُريبات المبيض على النمو وتهيئة البويضات للإباضة. ومع ازدياد حجم الجُريبات، تبدأ بإطلاق الإستروجين ومستوى منخفض من البروجستيرون في مجرى الدم.';

  @override
  String get cyA3FshP2 =>
