  @override
  String get cyA4S1P1 =>
      'التنقيط هو نزيف مهبلي خفيف يحدث خارج دورتك الطبيعية. إنه ليس تدفقاً — بل كميات صغيرة من الدم، تُلاحَظ غالباً فقط عند المسح أو كتبقّع خفيف على الملابس الداخلية. ولونه عادةً وردي أو أحمر فاتح أو بني، لا الأحمر الزاهي أو الغامق للدورة المعتادة. وفي معظم الحالات لا يحتاج إلى فوطة أو سدادة قطنية، بل إلى فوطة يومية على الأكثر.';

  @override
  String get cyA4S1P2 =>
      'التنقيط من أكثر التجارب شيوعاً وأكثرها سوء فهم في الدورة الشهرية. وقد يبدو مقلقاً في المرة الأولى التي يحدث فيها، لكن في غالبية الحالات يكون له سبب هرموني حميد تماماً. والتنقيط، أو الإفراز المهبلي الخفيف، قد يكون جزءاً طبيعياً تماماً من الدورة الشهرية.';

  @override
  String get cyA4S1P3 =>
