  @override
  String get cyA4Sub1P1 =>
      'النزيف في منتصف الدورة، الذي يأخذ عادةً شكل تنقيط خفيف، يرتبط في الغالب بالإباضة. ففي دراسة BioCycle، أبلغت نحو 5% من النساء عن نزيف منتصف الدورة خلال موعد الإباضة المتوقع أو حوله. وبما أن نزيف الإباضة غير شائع نسبياً، وقد يحدث عشوائياً أو نادراً، فمن السهل الخلط بينه وبين علامة على شيء آخر.';

  @override
  String get cyA4Sub1P2 =>
      'غالباً ما تسبب التغيرات في مستويات الإستروجين هذا النوع من النزيف — ويشير بعض الناس إلى نزيف الإباضة بنزيف اختراق الإستروجين. فقبيل الإباضة، يرتفع الإستروجين بحدة. ثم مباشرةً بعد إطلاق البويضة، ينخفض الإستروجين فجأةً بينما يبدأ البروجستيرون بالارتفاع. وقد يؤدي هذا التحول الهرموني السريع إلى تساقط جزء صغير من بطانة الرحم لفترة وجيزة، منتجاً تنقيطاً خفيفاً.';

  @override
  String get cyA4Sub1P3 =>
