  @override
  String get cyA4Sub2P1 =>
      'يعاني بعض الناس تنقيطاً بنياً فاتحاً أو وردياً في اليوم إلى الثلاثة أيام قبل بدء دورتهم فعلياً. ويحدث ذلك بسبب انخفاض البروجستيرون في نهاية الطور الأصفري، ما يجعل بطانة الرحم تبدأ بالتفكك قبل بدء التدفق الطمثي الكامل. ويُعتبر طبيعياً عندما لا يستمر أكثر من 3 أيام وتعقبه دورة طبيعية.';

  @override
