  @override
  String get cyA4Sub3P1 =>
      'في الدورات التي لا تحدث فيها الإباضة — وهو أمر شائع لدى المراهقات — تكون الأنماط الهرمونية أقل قابلية للتنبؤ. فبدون ارتفاع LH وما يتبعه من ارتفاع البروجستيرون، قد يتقلب الإستروجين بشكل غير منتظم، مسبّباً ما يُسمى نزيف اختراق الإستروجين. وهذا النوع من التنقيط شائع في أول 2 إلى 3 سنوات بعد أول دورة مع نضوج النظام الهرموني.';

