  @override
  String get cyA5S1P1 =>
      'اعتمدت الكلية الأمريكية لأطباء التوليد وأمراض النساء (ACOG) الدورة الشهرية رسمياً كعلامة حيوية عام 2015 — واضعةً إياها إلى جانب ضغط الدم ومعدل ضربات القلب ودرجة الحرارة ومعدل التنفس كمؤشر أساسي على الصحة العامة. وهذا ليس رمزياً. بل يعكس واقعاً سريرياً: فدورتك تستجيب لكل ما يحدث تقريباً في جسمك وفي حياتك.';

  @override
  String get cyA5S1P2 =>
      'حين تتأخر دورتك أو تكون غزيرة أو أخف من المعتاد أو ببساطة مختلفة عن الطبيعي، فهي لا تكون عشوائية إطلاقاً تقريباً. إنه نظام جسمك الهرموني يخبرك بأن شيئاً ما قد تغيّر — داخلياً أو خارجياً. وفهم ما قد يسبب تلك التغيرات يمنحك القدرة على تفسير دورتك بدل مجرد التفاعل معها.';

  @override
  String get cyA5S1P3 =>
      'سلسلة القيادة الهرمونية التي تدير دورتك تبدأ في الوطاء — وهو جزء من الدماغ يقع عند تقاطع جهازك العصبي وجهازك الصمّاوي واستجابتك للتوتر. فمستويات الكورتيزول المرتفعة تكبح الهرمون المطلِق لموجهة الغدد التناسلية (GnRH)، ما يؤدي إلى اضطراب نمو الجُريبات وغياب الإباضة وتغيرات في طول الدورة. وتسهم عوامل نفسية كالقلق والاكتئاب في زيادة اضطرابات الطمث، بينما تفاقم عوامل نمط الحياة — بما فيها سوء النوم والنظام الغذائي وعبء العمل المفرط — الاختلالات المرتبطة بالتوتر.';

