  @override
  String get cyA5StressP2 =>
      'قد يتداخل التوتر المزمن مع الهرمونات التي تنظّم الدورة الشهرية، وتحديداً الهرمون المطلِق لموجهة الغدد التناسلية (GnRH). وقد يؤدي هذا الاضطراب إلى دورات غير منتظمة أو حتى انقطاع الطمث. ويمكن للكورتيزول المرتفع أن يؤثر في الإباضة بكبح ارتفاع LH اللازم لها، ما يؤدي إلى دورات غير إباضية. وتحت التوتر، قد يحوّل الجسم أيضاً سلائف البروجستيرون لإنتاج مزيد من الكورتيزول — ظاهرة تُعرف بسرقة البريجنينولون — ما قد يخلّ أكثر بانتظام الطمث.';

  @override
  String get cyA5StressP3 =>
