  @override
  String get cyA6FlowResP1 =>
      'وجدت دراسة Apple Women\'s Health Study أن الأعراض الأكثر متابعةً كانت تقلصات البطن والانتفاخ والتعب — وقد عانى منها جميعاً أكثر من 60 بالمئة من المشاركات اللواتي سجّلن أعراضهنّ. وأبلغ أكثر من النصف عن حب الشباب والصداع. والجدير بالملاحظة أن أعراضاً أقل شهرةً مثل الإسهال وتغيرات النوم سجّلتها أيضاً 37 بالمئة من المشاركات. (PubMed Central)';

