  @override
  String get cyA6SympCrampsB =>
      'التقلصات الخفيفة في اليومين الأول والثاني طبيعية. أما التقلصات التي تبدأ قبل الدورة أو تستمر بعد اليومين الثاني والثالث أو تمتد باستمرار إلى أسفل الظهر والساقين فليست كذلك — وهي أحد الأعراض الأولية الرئيسية لبطانة الرحم المهاجرة. وجدت دراسة حلّلت 4.9 مليون دورة طبيعية لأكثر من 378,000 مستخدمة لتطبيق Clue أن تدفق الدورة وألمها من بين أعلى الأعراض المُتابَعة ذاتياً دلالةً للكشف عن حالات صحية تشمل بطانة الرحم المهاجرة ومتلازمة تكيس المبايض. (Medscape)';

  @override
