  @override
  String get cyDevIrregularB2 =>
      'خلال المراهقة، أكثر أسباب الدورات الشهرية غير المنتظمة شيوعاً هو عدم نضج محور الوطاء-الغدة النخامية-المبيض (HPO) — جهاز التحكم الهرموني الذي ينظم دورتك. وهذا طبيعي في السنوات القليلة الأولى بعد أول دورة لك.';

  @override
  String get cyDevIrregularB3 =>
      'ومع ذلك، ينبغي النظر في أسباب أخرى أيضاً. ففي السنة الأولى بعد أول حيض، 20% فقط من الدورات الشهرية إباضية. ويرتفع هذا إلى 25–35% في السنة الثانية، و45% في السنة الرابعة، وحتى 70% خلال السنوات 5 إلى 9 بعد أول حيض.';

  @override
  String get cyDevIrregularB4 =>
      'ما يصل إلى واحدة من كل أربع ممن يحضن لديها عدم انتظام في الطمث. ويمكن اعتبار دورتك الشهرية غير منتظمة إذا كانت دوراتك قصيرة على نحو لا يمكن التنبؤ به (أقل من 21 يوماً)، أو طويلة (أكثر من 35 يوماً)، أو متباعدة بأكثر من ثلاثة أشهر.';

  @override
  String get cyDevIrregularB5 =>
      'إذا استمر عدم الانتظام بعد سنتين إلى ثلاث سنوات من أول دورة لك، يستطيع الطبيب إجراء فحوصات هرمونية للحصول على صورة أوضح. إنه تحرٍّ مباشر يمكن أن يستبعد متلازمة تكيس المبايض، ومشكلات الغدة الدرقية، وحالات أخرى شائعة وقابلة للعلاج.';

  @override
  String get cyDevShortCycleB1 =>
      'دورة أقصر من 21 يوماً تعني أن دورتك تأتي بتواتر أكبر مما يُعدّ معتاداً. وقد يكون هذا أحياناً طبيعياً لدى المراهقات، خاصة في السنوات الأولى بعد أول دورة عندما لا يزال الجهاز الهرموني ينضج.';

  @override
  String get cyDevShortCycleB2 =>
      'وفقاً للإرشادات الدولية القائمة على الأدلة، تُعرَّف الدورات الأقصر من 21 يوماً في الفترة بين سنة و3 سنوات بعد أول حيض بأنها غير منتظمة وجديرة بالمراقبة.';

  @override
  String get cyDevShortCycleB3 =>
      'الدورات القصيرة باستمرار قد ترتبط أحياناً بحالة تُسمى قصور المرحلة الأصفرية، حيث تكون المرحلة التالية للإباضة قصيرة جداً، أو بمستويات منخفضة من البروجستيرون. كما قد تعكس ببساطة استجابة جسمك للتوتر، أو لتغيرات كبيرة في الوزن، أو لنقص تغذوي.';

  @override
  String get cyDevShortCycleB4 =>
      'تشمل الأسباب الإضافية التي ينبغي النظر فيها متلازمة تكيس المبايض، وقصور الغدة الدرقية، وارتفاع مستويات البرولاكتين، والخلل الوطائي الوظيفي. وإذا كانت دوراتك أقصر باستمرار من 21 يوماً لـ 3 دورات أو أكثر، فاذكري ذلك لطبيب. ويمكن لتحليل هرموني بسيط في الدم تحديد معظم الأسباب أو استبعادها بسرعة.';

  @override
  String get cyDevLongCycleB1 =>
      'دورة أطول من 35 يوماً تعني أن جسمك يأخذ وقتاً أطول من المعتاد بين الدورات. وهذا في الواقع أحد أكثر أنماط الطمث شيوعاً لدى المراهقات، لأن المحور الهرموني الذي يتحكم في الإباضة يستغرق عدة سنوات لينتظم بالكامل بعد أول دورة لك.';

  @override
  String get cyDevLongCycleB2 =>
      'وفقاً للإرشادات السريرية الدولية، تُعدّ الدورات الأطول من 45 يوماً في أول سنة إلى 3 سنوات بعد أول حيض، أو الأطول من 35 يوماً اعتباراً من 3 سنوات بعد أول حيض فصاعداً، غير منتظمة وتستدعي التقييم.';

  @override
  String get cyDevLongCycleB3 =>
      'أشارت الدراسات إلى أن الدورات الشهرية غير المنتظمة خلال البلوغ تنبئ بتطور متلازمة تكيس المبايض مستقبلاً — وإن كان هذا لا يعني أن كل دورة طويلة علامة على المتلازمة. فالتوتر، وخلل الغدة الدرقية، وارتفاع البرولاكتين، والعوامل التغذوية كلها أسباب شائعة بالقدر نفسه.';

  @override
  String get cyDevLongCycleB4 =>
      'وجد بحث من Apple Women\'s Health Study، حلّل 160,206 دورة شهرية لدى 15,586 مشاركة، أن من لديهنّ دورات غير منتظمة في مرحلة الحياة المبكرة كان لديهنّ باستمرار متوسطات أطول لطول الدورة في السنوات الإنجابية المبكرة، مع تضاؤل الفروق مع التقدم في العمر خلال العشرينيات والثلاثينيات.';

  @override
  String get cyDevLongCycleB5 =>
      'إذا كانت الدورات تتجاوز 35 يوماً باستمرار عبر 3 دورات أو أكثر، يستطيع الطبيب إجراء تحاليل دم للتحقق من مستويات الهرمونات بما فيها LH وFSH ووظيفة الغدة الدرقية والأندروجينات.';

  @override
  String get cyDevLongPeriodB1 =>
      'تستمر الدورة المعتادة بين 3 و7 أيام. والنزف الذي يستمر باستمرار بعد 8 أيام جدير بالتحري. ويُعرَّف النزف الطمثي الغزير (HMB) بأنه فقدان دم يتجاوز 80 مل أو نزف يستمر أكثر من 7 أيام لكل دورة.';

  @override
  String get cyDevLongPeriodB2 =>
      'تنجم الدورات الممتدة لدى المراهقات في أغلب الأحيان عن الدورات اللاإباضية — وهي دورات لا تحدث فيها إباضة — مما يؤدي إلى فرط نمو بطانة الرحم التي تستغرق وقتاً أطول للتساقط. وكثيراً ما تكون الدورات الشهرية غير منتظمة ولا إباضية في السنوات القليلة الأولى بعد أول حيض، ويزداد الوقت اللازم لإرساء دورات إباضية منتظمة مع تقدّم سن أول حيض.';

  @override
  String get cyDevLongPeriodB3 =>
      'تشمل الأسباب الأخرى خلل الغدة الدرقية، ومتلازمة تكيس المبايض، وفي بعض الحالات اضطراباً نزفياً كامناً. وانعدام الإباضة هو أكثر أسباب النزف الطمثي الغزير شيوعاً لدى المراهقات؛ والاضطراب النزفي الكامن هو ثاني أكثر الأسباب شيوعاً.';

  @override
  String get cyDevLongPeriodB4 =>
      'نحو 20% من جميع الفتيات المراهقات المصابات بالنزف الطمثي الغزير و33% ممن يُدخَلن المستشفى بسببه لديهنّ اضطراب نزفي كامن. وإذا كانت دوراتك تستمر باستمرار أكثر من 8 أيام، يستطيع الطبيب فحص مستويات الحديد لديك — فالنزف المطوّل قد يؤدي إلى فقر دم بعوز الحديد، الذي يسبب التعب وصعوبة التركيز.';

  @override
  String get cyDevHeavyB1 =>
      'النزف الطمثي الغزير — ويُسمى سريرياً غزارة الطمث — يُعرَّف بأنه فقدان دم مفرط يتداخل مع جودة حياتك الجسدية أو الاجتماعية أو العاطفية. ويُقدَّر حدوثه لدى نحو 37% من المراهقات. ولذا، رغم أنه قد يبدو مقلقاً، فأنت لستِ وحدك إطلاقاً.';

  @override
  String get cyDevHeavyB2 =>
      'أكثر أسباب النزف الطمثي الغزير شيوعاً لدى المراهقات هو خلل الإباضة، يليه اعتلالات التخثر — وهي حالات لا يتخثر فيها الدم بشكل سليم. وأكثر الاضطرابات النزفية الوراثية شيوعاً هو داء فون ويلبراند.';

  @override
  String get cyDevHeavyB3 =>
      'حتى في غياب فقر الدم، يمكن أن يسبب نضوب الحديد الناجم عن النزف الطمثي الغزير التعب وتراجع الإدراك، خاصةً في التعلّم اللفظي والذاكرة.';

  @override
  String get cyDevHeavyB4 =>
      'يدعو البحث إلى إجراء تقييم شامل للنزف لدى جميع المراهقات المصابات بالنزف الطمثي الغزير، حتى ضمن سنتهنّ الأولى بعد أول حيض. وإذا كنتِ تشبعين فوطة أو سدادة في أقل من ساعتين، أو تُخرِجين جلطات كبيرة، أو تشعرين بالدوار والتعب أثناء دورتك، فتحدثي إلى طبيب. تتوفر علاجات فعّالة — تشمل مكملات الحديد، والخيارات الهرمونية، وأدوية أخرى — يمكن أن تحسّن جودة الحياة بشكل كبير.';

